=My server is reporting the following problems:

Problems: {{ $json.problems }}

Full metrics:
{{ $json.summary }}

Analyze the issues and execute the necessary fix commands via SSH on my server at 192.168.100.177. After fixing, report what you did and the current status.

parameters.jsCode:
const output = $input.first().json.stdout;

const lines = output.split('\n');
const metrics = {};

lines.forEach(line => {
  const [key, value] = line.split(': ');
  metrics[key.trim()] = value ? value.trim() : '';
});

const cpu = parseFloat(metrics['CPU']);
const ram = parseFloat(metrics['RAM']);
const disco = parseFloat(metrics['Disco']);
const bateria = parseFloat(metrics['Bateria']);
const web = metrics['Web'];
const docker = metrics['Docker'];

const problems = [];

if (cpu > 80) problems.push(`CPU alta: ${cpu}%`);
if (ram > 85) problems.push(`RAM alta: ${ram}%`);
if (disco > 90) problems.push(`Disco lleno: ${disco}%`);
if (bateria < 20) problems.push(`Bateria baja: ${bateria}%`);
if (web !== '200') problems.push(`Web caída: ${web}`);

return [{
  json: {
    metrics,
    problems,
    hasProblems: problems.length > 0,
    summary: output
  }
}];
